# coding: utf-8
from lesson_authoring import entry as E
B=[['拉丁 per','穿过；遍及；彻底']]
M=B+[['拉丁 per- + meare → permeare','穿过去、通行']]
V=B+[['拉丁 per- + vadere → pervadere','走遍、扩散到各处']]
W=[
E('per','英弱读 /pə/、重读 /pɜː/；美 /pər/、重读 /pɜr/','每；按照；通过','把数量摊到一个单位上：每个人、每小时、每公里各算多少。','来自拉丁介词 per 穿过、通过；英语中的按单位计算义和按某项依据行事义都属于介词的用法。',B+[['拉丁及法语中的 per 结构 → 英语 per','通过、按某种方式 → 每、按照']],'20 dollars per hour 是每小时二十美元；as per your request 是按你的要求。前者用于数量和比率很常见，后者较正式，日常也能直接说 as you requested。','per person；per day；kilometres per hour；as per the instructions。','per 不等于每种位置都能替换 each。per student 放在数量后，each student 则能直接作主语；要看句子的结构。',('Each ticket costs twelve dollars per person.','票价为每人十二美元。'),('The machine produces sixty parts per minute.','这台机器每分钟生产六十个零件。'),sources=['https://www.etymonline.com/word/per','https://www.oxfordlearnersdictionaries.com/definition/english/per']),
E('permeate','英 /ˈpɜːmieɪt/；美 /ˈpɝmieɪt/','渗入；渗透；弥漫','像水进入海绵，慢慢穿过内部细小的空间。','来自拉丁 permeatus，permeare 的分词；per- 穿过 + meare 走、通过。',M+[['拉丁 permeatus → 英语 permeate','通过、渗透']],'水可以 permeate the soil，气味可以 permeate the room，某种观念也可以 permeate an organization。后两者不必真有液体，是把影响进入各处比成渗透。','permeate something；permeate through something；be permeated with something。','permeate 让人想到进入内部并扩散；cover 可能只是覆盖表面。两个词的空间画面不同。',('Water slowly permeated the dry soil.','水慢慢渗进干燥的土壤。'),('A sense of uncertainty permeated the whole organization.','整个组织都弥漫着不确定感。'),sources=['https://www.etymonline.com/word/permeate','https://en.wiktionary.org/wiki/permeate']),
E('permeable','英 /ˈpɜːmiəbəl/；美 /ˈpɝmiəbəl/','可渗透的；能让液体或气体通过的','材料没有完全堵死，水或气体能从里面穿过去。','来自拉丁 permeabilis，接 permeare；现代可对照 permeate 与 -able，但英语形容词出现更早。',M+[['拉丁 permeabilis → 英语 permeable','能够通过的 → 可渗透的']],'permeable paving 让雨水穿过路面，而不是全留在表面流走。permeable to water 指能透水；材料对一种东西可透，不代表对所有东西都可透。','permeable to water；permeable soil；a permeable membrane；permeable paving。','porous 说有孔隙，permeable 说能穿透。存在孔隙不一定表示孔隙彼此连通，因此两个词的重点不一样。',('The path uses permeable paving to let rainwater soak through.','这条步道使用可透水铺装，让雨水能够渗下去。'),('The membrane is permeable to water but blocks larger particles.','这层膜允许水通过，却会挡住较大的颗粒。'),sources=['https://www.etymonline.com/word/permeable','https://en.wiktionary.org/wiki/permeable']),
E('impermeable','英 /ɪmˈpɜːmiəbəl/；美 /ɪmˈpɝmiəbəl/','不渗透的；不透水或气的','像一道封住的屏障，指定的水或气体穿不过去。','im- 是否定前缀 in- 在 p 前的形式；来自法语 imperméable 或拉丁 impermeabilis，也可按 im- + permeable 理解。',M+[['拉丁 in- + permeabilis → impermeabilis','不能穿过的'],['法语 imperméable／英语 impermeable','不渗透的']],'impermeable to water 是不透水。这里必须留意“对什么不透”：防水层能阻挡水，并不自动说明它在任何条件下都挡住一切气体。比喻中 impermeable to criticism 说某人仿佛批评一点也听不进去。','impermeable to water；an impermeable layer；an impermeable barrier。','waterproof 强调防水用途，impermeable 更一般地谈某种物质能否通过；具体对象和条件仍靠上下文。',('An impermeable layer prevents water from reaching the wooden surface.','一层不透水的材料阻止水接触木质表面。'),('His confidence seemed impermeable to criticism.','他的自信仿佛完全不受批评影响。'),sources=['https://www.etymonline.com/word/impermeable','https://en.wiktionary.org/wiki/impermeable']),
E('permeability','英 /ˌpɜːmiəˈbɪləti/；美 /ˌpɝmiəˈbɪləti/','渗透性；透过性','把问题从“能不能透”改成“有多容易透过去”。','接法语 perméabilité，也可按 permeable + -ity 理解；-able 在名词里变为 -ability。',M+[['permeabilis → permeable／法语 perméabilité','可通过的；可通过性'],['英语 permeability','材料或边界的渗透性']],'soil permeability 是土壤让水等流体通过的能力；high permeability 说容易通过。社会分析也会讨论边界的 permeability，借此说人、信息或影响能有多大程度跨越边界。','high／low permeability；soil permeability；permeability to water。','permeability 是性质，permeation 是渗透过程。一个材料渗透性高，不等于在没有流体或推动条件时也正在渗透。',('The engineers measured the permeability of the soil.','工程师测量了土壤的渗透性。'),('The coating reduces the material’s permeability to water.','这层涂层降低了材料的透水性。'),sources=['https://www.etymonline.com/word/permeability','https://www.oxfordlearnersdictionaries.com/definition/english/permeability']),
E('permeation','英 /ˌpɜːmiˈeɪʃən/；美 /ˌpɝmiˈeɪʃən/','渗透；渗入过程','镜头连续跟着水走：它怎样进入材料、怎样从内部穿过去。','以拉丁 permeare 通过为基础的动作名词；英语 permeation 记录早于 permeate，不能硬排成英语动词先造出。',M+[['拉丁 permeare → 英语 permeation','通过 → 渗透这一过程']],'the permeation of water through a material 强调水穿过材料的过程。文章也可以谈观念对社会生活的 permeation，但这比普通的 spread 更正式、更强调进入内部。','permeation through a membrane；water permeation；prevent permeation。','permeation 是发生的过程，permeability 是让这种过程发生得容易还是困难的性质。',('The experiment measured the permeation of gas through the film.','实验测量了气体穿过薄膜的渗透过程。'),('The seal is designed to limit moisture permeation.','这种密封结构旨在减少水分渗入。'),sources=['https://www.etymonline.com/word/permeation','https://www.oxfordlearnersdictionaries.com/definition/english/permeation'])
]
